set-variable.value:
@{
        var body = context.Request.Body.As<JObject>(preserveContent: true);
        if (body["prompt"] != null)
        {
            return new JArray(new JObject(new JProperty("role", "user"), new JProperty("content", (string)body["prompt"]))).ToString();
        }
        return ((JArray)body["messages"]).ToString();
    }

send-request.set-body:
@{
          var messages = JArray.Parse((string)context.Variables["userMessages"]);
          var documents = new JArray();
          for (var i = 0; i < messages.Count; i++)
          {
              documents.Add(new JObject(new JProperty("id", i.ToString()), new JProperty("language", "en"), new JProperty("text", (string)messages[i]["content"])));
          }
          return new JObject(
              new JProperty("kind", "PiiEntityRecognition"),
              new JProperty("parameters", new JObject(
                  new JProperty("modelVersion", "2023-09-01"),
                  new JProperty("stringIndexType", "Utf16CodeUnit"),
                  new JProperty("loggingOptOut", true),
                  new JProperty("piiCategories", new JArray("Person", "Email", "PhoneNumber")))),
              new JProperty("analysisInput", new JObject(new JProperty("documents", documents)))).ToString();
      }

set-variable.value:
@{
        var messages = JArray.Parse((string)context.Variables["userMessages"]);
        var response = JObject.Parse((string)context.Variables["languageBody"]);
        var results = response["results"] as JObject;
        if ((string)response["kind"] != "PiiEntityRecognitionResults" || results == null) { throw new Exception("Invalid PII result envelope"); }
        var errors = results["errors"] as JArray;
        var documents = results["documents"] as JArray;
        if (errors == null || errors.Count != 0 || documents == null || documents.Count != messages.Count) { throw new Exception("Incomplete PII results"); }
        var seen = new HashSet<string>();
        var counts = new Dictionary<string, int>();
        var labels = new Dictionary<string, string> { { "Person", "PERSON" }, { "Email", "EMAIL" }, { "PhoneNumber", "PHONE" } };
        var total = 0;
        for (var i = 0; i < messages.Count; i++)
        {
            var id = i.ToString();
            var matching = documents.Where(d => (string)d["id"] == id).ToArray();
            if (matching.Length != 1 || !seen.Add(id)) { throw new Exception("Invalid PII document IDs"); }
            var document = matching[0];
            var entities = document["entities"] as JArray;
            var warnings = document["warnings"] as JArray;
            if (entities == null || warnings == null || warnings.Count != 0 || document["redactedText"]?.Type != JTokenType.String) { throw new Exception("Invalid or truncated PII document"); }
            var text = (string)messages[i]["content"];
            var cursor = 0;
            var rewritten = new StringBuilder();
            foreach (var entity in entities.OrderBy(e => (int)e["offset"]))
            {
                var category = (string)entity["category"];
                if (category == null || !labels.ContainsKey(category) || entity["offset"]?.Type != JTokenType.Integer || entity["length"]?.Type != JTokenType.Integer || entity["text"]?.Type != JTokenType.String) { throw new Exception("Invalid PII entity"); }
                var offset = (int)entity["offset"];
                var length = (int)entity["length"];
                if (offset < cursor || length <= 0 || offset > text.Length || length > text.Length - offset || text.Substring(offset, length) != (string)entity["text"]) { throw new Exception("Invalid PII entity span"); }
                counts[category] = counts.ContainsKey(category) ? counts[category] + 1 : 1;
                rewritten.Append(text.Substring(cursor, offset - cursor));
                rewritten.Append("[" + labels[category] + "_" + counts[category].ToString() + "]");
                cursor = offset + length;
                total++;
            }
            rewritten.Append(text.Substring(cursor));
            messages[i]["content"] = rewritten.ToString();
        }
        return new JObject(new JProperty("status", total == 0 ? "ALLOWED" : "REDACTED"), new JProperty("count", total), new JProperty("categories", new JArray(counts.Keys.OrderBy(k => k))), new JProperty("messages", messages)).ToString();
    }

return-response.set-body:
@{
              return new JObject(new JProperty("code", "BACKEND_NOT_CONFIGURED"),
                  new JProperty("message", "Gateway redaction completed. The guarded Foundry agent is not configured; no model was invoked."),
                  new JProperty("requestId", context.RequestId.ToString()),
                  new JProperty("telemetry", new JObject(new JProperty("apimValidation", "ALLOWED"), new JProperty("piiRedaction", JObject.Parse((string)context.Variables["redactionResult"])), new JProperty("foundry", "NOT_RUN")))).ToString();
          }

send-request.set-body:
@{
          var redaction = JObject.Parse((string)context.Variables["redactionResult"]);
          return new JObject(
              new JProperty("agent", new JObject(new JProperty("type", "agent_reference"), new JProperty("name", "{{pii-demo-agent-name}}"), new JProperty("version", "{{pii-demo-agent-version}}"))),
              new JProperty("input", redaction["messages"]),
              new JProperty("store", false),
              new JProperty("stream", false)).ToString();
      }

set-variable.value:
@{
        var backend = (IResponse)context.Variables["foundryResponse"];
        if (backend.StatusCode == 401 || backend.StatusCode == 403)
        {
            return new JObject(new JProperty("httpStatus", 502), new JProperty("code", "BACKEND_AUTHORIZATION_FAILED"), new JProperty("output", null)).ToString();
        }
        var body = backend.Body.As<JObject>();
        var code = "BACKEND_FAILED";
        var status = 502;
        var text = new StringBuilder();
        var errorCode = (string)body.SelectToken("error.code");
        var innerCode = (string)body.SelectToken("error.innererror.code");
        var filters = body.SelectToken("error.innererror.content_filter_result") as JObject;
        if (filters == null) { filters = body.SelectToken("error.innererror.content_filter_results") as JObject; }
        var annotations = body["content_filters"] as JArray ?? body.SelectToken("error.content_filters") as JArray ?? new JArray();
        var blocked = annotations.Where(a => (bool?)a["blocked"] == true).ToArray();
        if (blocked.Length != 0)
        {
            status = 422;
            code = "GUARDRAIL_BLOCKED";
            if (blocked.Any(a => (string)a["source_type"] == "completion" && (bool?)a.SelectToken("content_filter_results.personally_identifiable_information.filtered") == true)) { code = "PII_OUTPUT_BLOCKED"; }
            else if (blocked.Any(a => (string)a["source_type"] == "prompt" && (bool?)a.SelectToken("content_filter_results.jailbreak.filtered") == true)) { code = "JAILBREAK_BLOCKED"; }
            else if (blocked.Any(a => (string)a["source_type"] == "prompt" && (bool?)a.SelectToken("content_filter_results.personally_identifiable_information.filtered") == true)) { code = "PII_INPUT_BLOCKED"; }
        }
        else if (errorCode == "content_filter" || innerCode == "ResponsibleAIPolicyViolation" || (string)body.SelectToken("incomplete_details.reason") == "content_filter")
        {
            status = 422;
            code = "GUARDRAIL_BLOCKED";
            if (backend.StatusCode == 400 && filters != null && (bool?)filters.SelectToken("jailbreak.filtered") == true) { code = "JAILBREAK_BLOCKED"; }
            else if (filters != null && (bool?)filters.SelectToken("pii.filtered") == true)
            {
                if ((string)body.SelectToken("incomplete_details.reason") == "content_filter") { code = "PII_OUTPUT_BLOCKED"; }
                else if (backend.StatusCode == 400) { code = "PII_INPUT_BLOCKED"; }
            }
        }
        else if (backend.StatusCode == 429 && errorCode == "rate_limit_exceeded")
        {
            code = "BACKEND_RATE_LIMITED";
            status = 429;
        }
        else if (backend.StatusCode == 200 && (string)body["status"] == "completed" && body["error"]?.Type != JTokenType.Object)
        {
            var output = body["output"] as JArray;
            if (output == null) { throw new Exception("Missing agent output"); }
            foreach (var item in output)
            {
                if ((string)item["type"] != "message" || (string)item["role"] != "assistant") { continue; }
                if ((string)item["status"] != "completed") { throw new Exception("Incomplete assistant output"); }
                var content = item["content"] as JArray;
                if (content == null) { throw new Exception("Missing message content"); }
                foreach (var part in content)
                {
                    var type = (string)part["type"];
                    if (type != "output_text" && type != "refusal") { throw new Exception("Unsupported output content"); }
                    var value = type == "output_text" ? part["text"] : part["refusal"];
                    if (value?.Type != JTokenType.String) { throw new Exception("Invalid assistant text"); }
                    if (text.Length != 0) { text.AppendLine(); }
                    text.Append((string)value);
                }
            }
            if (text.Length == 0) { throw new Exception("Empty assistant output"); }
            code = "SAFE_RESPONSE";
            status = 200;
            if (Regex.IsMatch(text.ToString(), @"\bU\d{7}\b")) { code = "STUDENT_ID_OUTPUT_BLOCKED"; status = 422; text.Clear(); }
        }
        return new JObject(new JProperty("httpStatus", status), new JProperty("code", code), new JProperty("output", status == 200 ? text.ToString() : null)).ToString();
    }

return-response.set-body:
@{
          var result = JObject.Parse((string)context.Variables["safeResult"]);
          result.Remove("httpStatus");
          result["requestId"] = context.RequestId.ToString();
          result["telemetry"] = new JObject(new JProperty("apimValidation", "ALLOWED"), new JProperty("piiRedaction", JObject.Parse((string)context.Variables["redactionResult"])), new JProperty("foundry", (string)result["code"] == "SAFE_RESPONSE" ? "COMPLETED" : "BLOCKED_OR_FAILED"));
          return result.ToString();
      }

@{
          var stage = context.Variables.GetValueOrDefault<string>("stage", "validation");
          var code = context.LastError.Reason == "SubscriptionKeyNotFound" || context.LastError.Reason == "SubscriptionKeyInvalid" ? "SUBSCRIPTION_REQUIRED" : (context.LastError.Reason == "RateLimitExceeded" ? "RATE_LIMITED" : (stage == "validation" ? "INVALID_REQUEST" : (stage == "redaction" ? "PII_REDACTION_FAILED" : "BACKEND_FAILED")));
          return new JObject(new JProperty("code", code), new JProperty("message", "The request could not complete safely. No unverified response was released."), new JProperty("requestId", context.RequestId.ToString()), new JProperty("diagnostic", new JObject(new JProperty("stage", stage), new JProperty("reason", context.LastError.Reason), new JProperty("source", context.LastError.Source), new JProperty("backendStatus", context.Variables.GetValueOrDefault<int>("backendStatus", 0))))).ToString();
      }
